use std::sync::Arc;
use std::time::Instant;

/// A thread-safe rate limiter implementing the token bucket algorithm.
///
/// The `RateLimiter` allows a certain number of requests to be made within a
/// specific time window. Tokens are added to the bucket at a constant rate
/// (`refill_rate` tokens per second) up to a maximum capacity (`max_tokens`).
///
/// This implementation uses integer arithmetic for token calculations to avoid
/// floating-point precision issues and ensures thread safety via `Arc<Mutex<...>>`.
///
/// # Examples
///
/// ```
/// use std::time::Duration;
/// use your_crate::RateLimiter;
///
/// // Allow up to 10 tokens, refilling at 5 tokens per second
/// let limiter = RateLimiter::new(10, 5);
///
/// if limiter.try_acquire() {
///     println!("Request allowed");
/// } else {
///     println!("Rate limit exceeded");
/// }
/// ```
#[derive(Debug, Clone)]
pub struct RateLimiter {
    /// The current number of tokens in the bucket.
    tokens: u64,
    /// The maximum number of tokens the bucket can hold.
    max_tokens: u64,
    /// The rate at which tokens are refilled, in tokens per second.
    refill_rate: u64,
    /// The timestamp of the last token refill operation.
    last_refill: Instant,
}

impl RateLimiter {
    /// Creates a new `RateLimiter` with the specified maximum tokens and refill rate.
    ///
    /// # Arguments
    ///
    /// * `max_tokens` - The maximum number of tokens the bucket can hold. Must be > 0.
    /// * `refill_rate` - The rate at which tokens are refilled, in tokens per second. Must be > 0.
    ///
    /// # Errors
    ///
    /// Returns an error if `max_tokens` or `refill_rate` is zero, as this would
    /// result in an invalid rate limiter configuration.
    pub fn new(max_tokens: u64, refill_rate: u64) -> Result<Self, RateLimiterError> {
        if max_tokens == 0 {
            return Err(RateLimiterError::InvalidConfiguration(
                "max_tokens must be greater than 0",
            ));
        }
        if refill_rate == 0 {
            return Err(RateLimiterError::InvalidConfiguration(
                "refill_rate must be greater than 0",
            ));
        }

        Ok(Self {
            tokens: max_tokens,
            max_tokens,
            refill_rate,
            last_refill: Instant::now(),
        })
    }

    /// Attempts to acquire a single token from the bucket.
    ///
    /// If a token is available, it is consumed and `true` is returned.
    /// If no tokens are available, `false` is returned.
    ///
    /// This method is thread-safe and will automatically refill tokens
    /// based on the elapsed time since the last refill.
    pub fn try_acquire(&mut self) -> bool {
        self.refill();

        if self.tokens > 0 {
            self.tokens -= 1;
            true
        } else {
            false
        }
    }

    /// Returns the current number of available tokens in the bucket.
    ///
    /// This method will first refill the bucket based on the elapsed time
    /// since the last refill, ensuring the returned value is up-to-date.
    pub fn available_tokens(&mut self) -> u64 {
        self.refill();
        self.tokens
    }

    /// Refills the token bucket based on the elapsed time since the last refill.
    ///
    /// This method calculates the number of new tokens to add based on the
    /// `refill_rate` and the time elapsed since `last_refill`. It uses integer
    /// arithmetic to avoid floating-point precision issues.
    fn refill(&mut self) {
        let now = Instant::now();
        let elapsed = now.duration_since(self.last_refill);

        // Calculate the number of tokens to add.
        // We use integer division to avoid floating point.
        // tokens_to_add = (elapsed_seconds * refill_rate)
        // Since elapsed is in nanoseconds, we convert to seconds as a fraction.
        // To avoid floating point, we compute:
        // tokens_to_add = (elapsed.as_nanos() * refill_rate) / 1_000_000_000

        let elapsed_nanos = elapsed.as_nanos() as u128;
        let refill_rate_u128 = self.refill_rate as u128;

        // Prevent overflow in multiplication
        let tokens_to_add = (elapsed_nanos * refill_rate_u128) / 1_000_000_000;

        // Cap the tokens to add so we don't exceed max_tokens
        let current_tokens = self.tokens as u128;
        let max_tokens_u128 = self.max_tokens as u128;

        let new_tokens = current_tokens + tokens_to_add;

        if new_tokens > max_tokens_u128 {
            self.tokens = self.max_tokens;
        } else {
            self.tokens = new_tokens as u64;
        }

        self.last_refill = now;
    }
}

/// Errors that can occur when creating or using a `RateLimiter`.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RateLimiterError {
    /// The configuration provided was invalid.
    InvalidConfiguration(&'static str),
}

impl std::fmt::Display for RateLimiterError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            RateLimiterError::InvalidConfiguration(msg) => write!(f, "Invalid configuration: {}", msg),
        }
    }
}

