package healthcheck

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"net"
	"net/http"
	"sync"
	"time"
)

// Status represents the overall health status of the service.
type Status string

const (
	StatusOK       Status = "ok"
	StatusDegraded Status = "degraded"
	StatusDown     Status = "down"
)

// CheckResult represents the result of a single health check.
type CheckResult struct {
	Status  Status `json:"status"`
	Message string `json:"message,omitempty"`
}

// HealthResponse is the JSON structure returned by the /healthz endpoint.
type HealthResponse struct {
	Status string            `json:"status"`
	Checks map[string]any    `json:"checks"`
}

// Server manages the health check HTTP server.
type Server struct {
	addr   string
	checks map[string]func() error
	server *http.Server
	mu     sync.RWMutex
}

// NewServer creates a new health check server instance.
func NewServer(addr string, checks map[string]func() error) *Server {
	if checks == nil {
		checks = make(map[string]func() error)
	}
	return &Server{
		addr:   addr,
		checks: checks,
	}
}

// Start starts the HTTP server. It blocks until the server is stopped or an error occurs.
func (s *Server) Start() error {
	if s.addr == "" {
		return errors.New("healthcheck: address cannot be empty")
	}

	mux := http.NewServeMux()
	mux.HandleFunc("/healthz", s.handleHealth)

	s.server = &http.Server{
		Addr:         s.addr,
		Handler:      mux,
		ReadTimeout:  5 * time.Second,
		WriteTimeout: 5 * time.Second,
		IdleTimeout:  10 * time.Second,
	}

	// Create a listener to check for port conflicts early
	listener, err := net.Listen("tcp", s.addr)
	if err != nil {
		return fmt.Errorf("healthcheck: failed to listen on %s: %w", s.addr, err)
	}

	// Serve with the pre-created listener
	err = s.server.Serve(listener)
	if err != nil && !errors.Is(err, http.ErrServerClosed) {
		return fmt.Errorf("healthcheck: server error: %w", err)
	}

	return nil
}

// Stop gracefully shuts down the server.
func (s *Server) Stop(ctx context.Context) error {
	s.mu.Lock()
	server := s.server
	s.mu.Unlock()

	if server == nil {
		return nil
	}

	err := server.Shutdown(ctx)
	if err != nil {
		return fmt.Errorf("healthcheck: shutdown error: %w", err)
	}

	return nil
}

// handleHealth is the HTTP handler for the /healthz endpoint.
func (s *Server) handleHealth(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method Not Allowed", http.StatusMethodNotAllowed)
		return
	}

	s.mu.RLock()
	checks := s.checks
	s.mu.RUnlock()

	response := s.evaluateChecks(checks)

	w.Header().Set("Content-Type", "application/json")

	// Determine HTTP status code based on health status
	var httpStatus int
	switch response.Status {
	case string(StatusOK):
		httpStatus = http.StatusOK
	case string(StatusDegraded):
		httpStatus = http.StatusOK // Degraded is still "up" but not fully healthy
	case string(StatusDown):
		httpStatus = http.StatusServiceUnavailable
	default:
		httpStatus = http.StatusInternalServerError
	}

	w.WriteHeader(httpStatus)

	encoder := json.NewEncoder(w)
	if err := encoder.Encode(response); err != nil {
		// Log error in production; for now, we can't do much as headers are sent
		_ = err
	}
}

// evaluateChecks runs all registered checks and determines the overall status.
func (s *Server) evaluateChecks(checks map[string]func() error) HealthResponse {
	checkResults := make(map[string]any, len(checks))
	overallStatus := StatusOK
	hasDegraded := false
	hasDown := false

	for name, checkFunc := range checks {
		if checkFunc == nil {
			checkResults[name] = CheckResult{
				Status:  StatusDown,
				Message: "check function is nil",
			}
			hasDown = true
			continue
		}

		err := checkFunc()
		if err != nil {
			checkResults[name] = CheckResult{
				Status:  StatusDown,
				Message: err.Error(),
			}
			hasDown = true
		} else {
			checkResults[name] = CheckResult{
				Status: StatusOK,
			}
		}
	}

	if hasDown {
		overallStatus = StatusDown
	} else if hasDegraded {
		overallStatus = StatusDegraded
	}

	return HealthResponse{
		Status: string(overallStatus),
		Checks: checkResults,
	}
}

